<template>
    <Layout>
            <div class="bg-overlay bg-overlay-pattern opacity-50"></div>
            <b-container class="position-relative text-center" style="z-index: 2;">
                <div class="d-flex flex-column align-items-center pt-3 pb-2">

                    <template v-if="stage === 'scanning'">
                        <h6 class="fs-13 fw-semibold text-primary mb-1">Scan QR Code</h6>
                        <p class="fs-11 text-muted mb-2 px-4">Point your camera at a session or exhibitor booth QR code.</p>
                        <div class="mt-1 d-flex justify-content-center align-items-center box-wrapper">
                            <div id="qr-reader"></div>
                        </div>
                    </template>

                    <template v-else-if="stage === 'confirming'">
                        <h6 class="fs-13 fw-semibold text-primary mb-1">Confirm Your Attendance</h6>
                        <p class="fs-11 text-muted mb-3 px-4">To confirm attendance, please face the camera and click scan.</p>

                        <div class="face-stage mb-3">
                            <div class="face-circle">
                                <video ref="video" autoplay playsinline muted class="face-video"></video>
                                <div class="face-flash" v-if="flashActive"></div>
                                <div class="face-result face-result-success" v-if="resultState === 'success'">
                                    <i class="ri-check-line"></i>
                                </div>
                                <div class="face-result face-result-error" v-else-if="resultState === 'error'">
                                    <i class="ri-close-line"></i>
                                </div>
                            </div>
                        </div>

                        <button
                            type="button"
                            class="btn btn-warning btn-sm rounded-pill fs-11 px-4 waves-effect waves-light"
                            :disabled="isSubmitting || !!resultState"
                            @click="captureFace"
                        >
                            <span class="spinner-border spinner-border-sm me-1" v-if="isSubmitting"></span>
                            <i class="ri-camera-fill me-1" v-else></i>Scan
                        </button>
                        <div>
                            <button
                                type="button"
                                class="btn btn-link btn-sm fs-10 text-muted mt-2"
                                :disabled="isSubmitting"
                                @click="cancelConfirm"
                            >Cancel</button>
                        </div>
                    </template>

                </div>
            </b-container>
        <Notify ref="notify"/>
    </Layout>
</template>
<script>
import axios from 'axios';
import Notify from './notify.vue';
import Layout from "@/layouts/main.vue";
import { Html5Qrcode } from "html5-qrcode";
export default {
    components: { Layout, Notify },
    data(){
        return {
            participant: this.$store.state.auth.user.data,
            qrScanner: null,
            stage: 'scanning',
            decodedText: null,
            cameraStream: null,
            isSubmitting: false,
            flashActive: false,
            resultState: null
        }
    },
     watch: {
        '$store.state.data.notifier': {
            handler(newVal) {
                this.$nextTick(() => { // wait until DOM updates
            if (newVal && this.$refs.notify) {
                this.$refs.notify.show();
            } else {
                console.log('aw');
            }
        });
            },
            immediate: true, // run immediately on component mount (optional)
            deep: true // set true only if notifier is an object and you need nested changes
        }
    },
    mounted() {
        this.$store.commit('data/NOTIFY_USER', null);
        this.startScanner();
    },
    beforeUnmount() {
        this.stopScanner();
        this.stopFaceCamera();
    },
    methods: {
        async startScanner() {
            this.stage = 'scanning';
            this.decodedText = null;
            this.resultState = null;
            await this.$nextTick();
            const config = { fps: 10, qrbox: { width: 190, height: 190 } };

            this.qrScanner = new Html5Qrcode("qr-reader");

            try {
                await this.qrScanner.start(
                    { facingMode: "environment" },
                    config,
                    async (decodedText) => {
                        // Stop immediately to avoid duplicate reads
                        await this.qrScanner.stop();
                        this.decodedText = decodedText;
                        await this.checkAndConfirm(decodedText);
                    },
                    (errorMessage) => {
                        console.warn("QR Scan Error", errorMessage);
                    }
                );
            } catch (err) {
                console.error("Failed to start scanner", err);
            }
        },
        stopScanner() {
            if (this.qrScanner) {
                this.qrScanner.stop().then(() => {
                    this.qrScanner.clear();
                    this.qrScanner = null;
                }).catch(err => {
                    console.error("Failed to stop scanner", err);
                });
            }
        },
        async checkAndConfirm(decodedText) {
            try {
                const check = await axios.post('/sessions/attendance/check', {
                    participant_id: this.participant.id,
                    session: decodedText
                });

                if (check.data.status && !check.data.already) {
                    await this.openFaceConfirm();
                    return;
                }

                this.$store.commit('data/NOTIFY_USER', check.data.message || 'Unable to process this QR code.');
            } catch ({ response }) {
                this.$store.commit('data/NOTIFY_USER', response?.data?.message || 'Unable to process this QR code.');
            }
            await this.startScanner();
        },
        async openFaceConfirm() {
            this.stage = 'confirming';
            await this.$nextTick();
            try {
                this.cameraStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'user' } });
                this.$refs.video.srcObject = this.cameraStream;
            } catch (e) {
                console.error('Failed to start face camera', e);
                this.$store.commit('data/NOTIFY_USER', 'Camera access is required to confirm your attendance.');
                await this.startScanner();
            }
        },
        stopFaceCamera() {
            if (this.cameraStream) {
                this.cameraStream.getTracks().forEach(track => track.stop());
                this.cameraStream = null;
            }
        },
        async cancelConfirm() {
            this.stopFaceCamera();
            await this.startScanner();
        },
        async captureFace() {
            if (this.isSubmitting || this.resultState) return;

            const video = this.$refs.video;
            const canvas = document.createElement('canvas');
            canvas.width = video.videoWidth;
            canvas.height = video.videoHeight;
            canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);

            this.flashActive = true;
            setTimeout(() => { this.flashActive = false; }, 200);

            const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/jpeg'));
            const formData = new FormData();
            formData.append('participant_id', this.participant.id);
            formData.append('session', this.decodedText);
            formData.append('image', blob, 'capture.jpg');

            this.isSubmitting = true;
            try {
                const response = await axios.post('/sessions/attendance', formData, {
                    headers: { 'Content-Type': 'multipart/form-data' }
                });

                this.resultState = response.data.status ? 'success' : 'error';
            } catch (e) {
                this.resultState = 'error';
            } finally {
                this.isSubmitting = false;
                setTimeout(() => {
                    this.stopFaceCamera();
                    this.startScanner();
                }, 1500);
            }
        }
    },
};
</script>
<style>
.box-wrapper {
  width: 90vw;
  max-width: 330px;
  aspect-ratio: 1 / 1;   /* always square */
  margin: 0 auto;
  border: 2px solid #ccc;
  border-radius: 12px;
  overflow: hidden;      /* 🚀 keeps child inside the box */
  display: flex;
  justify-content: center;
  align-items: center;
}

#qr-reader {
  width: 100%;
  height: 100%;
  max-width: 290px;      /* ✅ matches your qrbox size */
  max-height: 290px;
}

#qr-reader video {
  object-fit: cover;     /* ✅ keeps video inside box */
  width: 100% !important;
  height: 100% !important;
}

.face-stage {
    width: 70vw;
    max-width: 260px;
    aspect-ratio: 1 / 1;
    margin: 0 auto;
}

.face-circle {
    position: relative;
    width: 100%;
    height: 100%;
    border-radius: 50%;
    overflow: hidden;
    border: 4px solid #ccc;
    background-color: #f1f3f5;
}

.face-video {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transform: scaleX(-1);
}

.face-flash {
    position: absolute;
    inset: 0;
    background-color: #ffffff;
    animation: face-flash-fade 0.2s ease-out forwards;
}

@keyframes face-flash-fade {
    from { opacity: 0.9; }
    to { opacity: 0; }
}

.face-result {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    animation: face-result-pop 0.25s ease;
}

.face-result i {
    color: #ffffff;
    font-size: 3.5rem;
}

.face-result-success {
    background-color: rgba(52, 211, 153, 0.85);
}

.face-result-error {
    background-color: rgba(220, 53, 69, 0.85);
}

@keyframes face-result-pop {
    from { opacity: 0; transform: scale(0.6); }
    to { opacity: 1; transform: scale(1); }
}
</style>
